SELECT COALESCE(s.date_key, r.date_key) AS date_key, COALESCE(s.i_category, r.i_category) AS i_category, COALESCE(total_sales, 0) AS total_sales, COALESCE(total_returns, 0) AS total_returns, COALESCE(total_sales, 0) - COALESCE(total_returns, 0) AS net_margin, CASE WHEN COALESCE(total_sales, 0) - COALESCE(total_returns, 0) > 0 THEN 'PROFIT' ELSE 'LOSS' END AS margin_status, SUM(COALESCE(total_sales, 0) - COALESCE(total_returns, 0)) OVER (PARTITION BY COALESCE(s.i_category, r.i_category) ORDER BY COALESCE(s.date_key, r.date_key) ROWS UNBOUNDED PRECEDING) AS cumulative_margin_by_category, ROW_NUMBER() OVER (PARTITION BY COALESCE(s.i_category, r.i_category) ORDER BY (COALESCE(total_sales, 0) - COALESCE(total_returns, 0)) DESC) AS rank_within_category FROM ( SELECT ws.ws_sold_date_sk AS date_key, i.i_category, SUM(ws.ws_net_paid_inc_tax) AS total_sales, SUM(ws.ws_net_profit) AS total_profit, SUM(ws.ws_quantity) AS total_qty FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk GROUP BY ws.ws_sold_date_sk, i.i_category ) s FULL OUTER JOIN ( SELECT wr.wr_returned_date_sk AS date_key, i.i_category, SUM(wr.wr_net_loss) AS total_returns, SUM(wr.wr_return_quantity) AS total_return_qty FROM web_returns wr JOIN item i ON wr.wr_item_sk = i.i_item_sk GROUP BY wr.wr_returned_date_sk, i.i_category ) r ON s.date_key = r.date_key AND s.i_category = r.i_category ORDER BY i_category, date_key
